import sys

def main():
    data = sys.stdin.read().strip()
    if not data:
        return
    X = int(data)
    total = 2025  # sum of 1..9 squared
    count = 0
    for i in range(1, 10):
        if X % i == 0:
            j = X // i
            if 1 <= j <= 9:
                count += 1
    result = total - count * X
    print(result)

if __name__ == "__main__":
    main()
