from typing import List

class Solution:
    def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
        n = len(nums)
        res = 0
        # Precompute prefix sums for cost calculation
        pref = [0] * (n + 1)
        for i in range(n):
            pref[i+1] = pref[i] + nums[i]
        # Brute force all subarrays
        for l in range(n):
            cur_max = nums[l]
            cost = 0
            for r in range(l+1, n):
                if nums[r] < cur_max:
                    cost += cur_max - nums[r]
                else:
                    cur_max = nums[r]
                if cost <= k:
                    res += 1
            # single element subarray
            res += 1
        return res
